const row = $input.first().json || {};
const body = row.body && typeof row.body === 'object' ? row.body : row;
return [{ json: {
  ...body,
  project_id: body.project_id || '',
  selected_concept_id: body.selected_concept_id || body.concept_id || '',
  concept_context_path: body.concept_context_path || body.context_path || '',
  review_after_generation: true,
} }];

const process = require('process');
const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const PROJECT_ROOT = process.env.TIKTOK_WORKFLOW_ROOT || process.env.PROJECT_ROOT || process.cwd();
const DATA_ROOT = require('process').env.WORKFLOW_DATA_ROOT || (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'workflow-data') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data')) || require('process').env.AI_VIDEO_RUNTIME_ROOT || PROJECT_ROOT;
const contextDir = require('path').join(DATA_ROOT, '.n8n-local-cache', 'concept-context');
const selectedDir = require('path').join(DATA_ROOT, '.n8n-local-cache', 'selected-concepts');
const projectDir = require('path').join(DATA_ROOT, '.n8n-local-cache', 'project-state');
fs.mkdirSync(selectedDir, { recursive: true });
fs.mkdirSync(projectDir, { recursive: true });

const projectId = String(row.project_id || '').trim();
const selectedConceptId = String(row.selected_concept_id || '').trim();
const contextPath = String(row.concept_context_path || '').trim() || path.join(contextDir, 'concept_context_' + projectId + '.json');

if (!projectId) {
  throw new Error('concept_select_restore：缺少 project_id');
}
if (!selectedConceptId) {
  throw new Error('concept_select_restore：缺少 selected_concept_id');
}
if (!fs.existsSync(contextPath)) {
  throw new Error('concept_select_restore：concept_context 不存在 ' + contextPath);
}

const context = JSON.parse(fs.readFileSync(contextPath, 'utf8'));
const concepts = Array.isArray(context.creative_concepts)
  ? context.creative_concepts
  : JSON.parse(context.creative_concepts_json || '[]');
if (!Array.isArray(concepts) || !concepts.length) {
  throw new Error('concept_select_restore：creative_concepts 为空');
}

const selectedIndex = concepts.findIndex((concept) => String(concept.concept_id || '') === selectedConceptId);
if (selectedIndex < 0) {
  throw new Error('concept_select_restore：selected_concept_id 未匹配到创意方向 ' + selectedConceptId);
}


const selectedConcept = concepts[selectedIndex];

// Read user revision overrides and merge into final concept
const revisionDir = path.join(DATA_ROOT, '.n8n-local-cache', 'concept-revisions');
const revisionFilePath = path.join(revisionDir, 'concept_revisions_' + projectId.replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
let revisionFields = {};
try {
  if (fs.existsSync(revisionFilePath)) {
    // concept_revisions structure: { revisions: { concept_id: { fields: {...} } } }
    const revData = JSON.parse(fs.readFileSync(revisionFilePath, 'utf8'));
    const entry = (revData.revisions || {})[selectedConceptId] || {};
    if (entry.fields && typeof entry.fields === 'object') revisionFields = entry.fields;
  }
} catch (e) {}
const finalConcept = { ...selectedConcept, ...revisionFields };
const selectedPayload = {
  project_id: projectId,
  selected_concept_id: selectedConceptId,
  selected_concept_index: selectedIndex,
  selected_concept_json: finalConcept,
  selected_at: new Date().toISOString(),
};
const selectedPath = path.join(selectedDir, 'selected_concept_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
fs.writeFileSync(selectedPath, JSON.stringify(selectedPayload, null, 2));
const projectStatePath = path.join(projectDir, 'project_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
fs.writeFileSync(projectStatePath, JSON.stringify({
  project_id: projectId,
  product_name: context.product_name || '',
  target_market: context.target_market || '',
  target_language: context.target_language || '',
  creative_task_type: context.creative_task_type || '',
  selected_concept_id: selectedConceptId,
  status: row.manual_regeneration_requested ? 'storyboard_regenerating' : 'concept_selected',
  updated_at: new Date().toISOString(),
}, null, 2));

return [{ json: {
  ...context,
  project_id: projectId,
  selected_concept_id: selectedConceptId,
  selected_concept_index: selectedIndex,
  selected_concept_name: finalConcept.concept_name || '',
  selected_concept_json: JSON.stringify(finalConcept),
  selected_concept: finalConcept,
  concept_context_path: contextPath,
  selected_concept_record_path: selectedPath,
  status: row.manual_regeneration_requested ? 'storyboard_regenerating' : 'concept_selected',
  target_user: finalConcept.target_user || '',
  usage_scene: finalConcept.usage_scene || '',
  visual_expression: finalConcept.visual_expression || '',
  hook_strategy: finalConcept.hook_strategy || '',
  model_profile: finalConcept.model_profile || '',
  core_selling_angle: finalConcept.core_selling_angle || '',
  why_it_fits_tiktok: finalConcept.why_it_fits_tiktok || '',
} }];

const fs = require('fs');
const path = require('path');
const os = require('os');

const input = $input.first();
const baseJson = input?.json || {};
const baseBinary = input?.binary || {};

function projectRoot() {
  const env = require('process').env || {};
  const candidates = [env.TIKTOK_WORKFLOW_ROOT, env.PROJECT_ROOT, require('process').cwd()].filter(Boolean);
  for (const root of candidates) {
    try { if (fs.existsSync(path.join(root, 'prompts', 'prompt_center.json'))) return root; } catch (_e) {}
  }
  throw new Error('Prompt Library: prompts/prompt_center.json not found. Checked: ' + candidates.join(', '));
}

function readJsonIfExists(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    }
  } catch (error) {}
  return {};
}

const root = projectRoot();
const prompts = readJsonIfExists(path.join(root, 'prompts', 'prompt_center.json'));
if (!Object.keys(prompts).length) {
  throw new Error('Prompt Library: 无法读取 prompts/prompt_center.json，请检查 TIKTOK_WORKFLOW_ROOT/PROJECT_ROOT 或项目目录位置');
}

const legacy = readJsonIfExists(path.join(root, 'tiktok-workflow-prompts.json'));
const fallbackStoryboardGrid = {
  cols: 3,
  rows: 2,
  panel_aspect: '9:16',
  normalize_canvas_aspect: '27:32',
  supported_panel_counts: [6],
  supported_layouts: { '6': '3x2 => 27:32' },
  crop_inset_ratio: 0.01,
  output_mime_type: 'image/jpeg',
  output_extension: 'jpg',
  jpeg_quality: 90,
  panel_output_width: 1080,
  panel_output_height: 1920,
  panel_order: 'row_major_left_to_right',
};
const fallbackCreativeTaskTypeMapping = {
  _meta: { version: 'runtime-fallback', description: '最小创作任务映射，完整配置优先来自 prompt_center.json' },
  '种草': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '口播': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '开箱': { video_type: 'pure_display_or_light_voiceover', recommended_grid: '6_grid' },
  '产品展示': { video_type: 'mixed', recommended_grid: '6_grid' },
  '痛点前置': { video_type: 'local_voiceover', recommended_grid: '6_grid' },
  '自由创作': { video_type: 'mixed', recommended_grid: '6_grid' },
  '故事剧情带货': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '真实故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
  '爆点故事剧情': { video_type: 'story_drama', recommended_grid: '6_grid' },
};

const runtimePrompts = {
  ...prompts,
  storyboard_grid: prompts.storyboard_grid || legacy.storyboard_grid || fallbackStoryboardGrid,
  creative_task_type_mapping: prompts.creative_task_type_mapping || legacy.creative_task_type_mapping || fallbackCreativeTaskTypeMapping,
};

return [{ json: { ...baseJson, ...runtimePrompts }, binary: baseBinary }];

const input = $input.item.json || {};

const rawConcepts = input.creative_concepts_json;
if (!rawConcepts) {
  throw new Error('creative_concepts_json 为空，无法提取选中方向');
}

let concepts;
try {
  concepts = JSON.parse(rawConcepts);
} catch (error) {
  throw new Error('creative_concepts_json 不是合法 JSON: ' + error.message);
}

if (!Array.isArray(concepts) || concepts.length === 0) {
  throw new Error('creative_concepts_json 解析后不是有效数组');
}

const selectedIndex = Number(input.selected_concept_index ?? 0);
if (selectedIndex < 0 || selectedIndex >= concepts.length) {
  throw new Error(`selected_concept_index 超出范围，当前值: ${selectedIndex}`);
}

const selectedConcept = concepts[selectedIndex];

return [
  {
    json: {
      ...input,
      project_id: input.project_id || '',
      product_name: input.product_name || '',
      target_market: input.target_market || '',
      target_language: input.target_language || '',
      creative_task_type: input.creative_task_type || '',
      director_status: input.director_status || '',
      product_understanding_json: input.product_understanding_json || '',
      audience_persona_json: input.audience_persona_json || '',
      tiktok_content_strategy_json: input.tiktok_content_strategy_json || '',
      creative_concepts_json: input.creative_concepts_json || '',
      selected_concept_index: selectedIndex,
      selected_concept_name: input.selected_concept_name || selectedConcept.concept_name || '',
      selected_concept_json: JSON.stringify(selectedConcept),
      selected_concept: selectedConcept,
      concept_count: input.concept_count || concepts.length,
      created_at: input.created_at || ''
    }
  }
];

const fs = require('fs');
const item = $input.first();
const binary = item.binary || {};
const row = item.json || {};

const imagePaths = Array.isArray(row.product_image_local_paths) ? row.product_image_local_paths : [];
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const image1Path = row.image_1_path || imagePaths[0] || metaImages[0]?.path || '';
const image2Path = row.image_2_path || imagePaths[1] || metaImages[1]?.path || '';
const imageCount = Number(row.product_image_count ?? row.image_count ?? imagePaths.length ?? metaImages.length ?? 0);

// ── Guard: verify file existence before attempting to read ─────────────────
if (imageCount > 0) {
  const requiredPaths = [];
  if (imageCount >= 1 && image1Path) requiredPaths.push(image1Path);
  if (imageCount >= 2 && image2Path) requiredPaths.push(image2Path);
  const missingPaths = requiredPaths.filter(p => !fs.existsSync(p));
  if (missingPaths.length > 0) {
    throw new Error(
      '产品图片缓存文件不存在，无法组装脚本请求体。\n' +
      'project_id: ' + (row.project_id || '(unknown)') + '\n' +
      '缺失路径（共 ' + missingPaths.length + ' 个）：\n' +
      missingPaths.map(p => '  ' + p).join('\n') + '\n' +
      '请重新从表单上传图片并重新生成创意方向，或将缺失图片手动复制到上述路径后重试。'
    );
  }
}

function readImageBase64(binaryKey, pathValue) {
  if (pathValue && fs.existsSync(pathValue)) {
    return fs.readFileSync(pathValue).toString('base64');
  }
  try {
    return this.helpers.getBinaryDataBuffer(0, binaryKey).then((buf) => buf.toString('base64'));
  } catch (error) {
    return '';
  }
}

const image1Base64 = imageCount >= 1 ? await readImageBase64.call(this, 'product_images_0', image1Path) : '';
const image2Base64 = imageCount >= 2 ? await readImageBase64.call(this, 'product_images_1', image2Path) : '';
const mime1 = binary.product_images_0?.mimeType || row.image_1_mime || metaImages[0]?.mimeType || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || row.image_2_mime || metaImages[1]?.mimeType || 'image/jpeg';

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const s = prompts.script;

// P12-H1b-A: safe automatic retry augmentation (additive; no contract change).
// Active ONLY when serve sets row.script_safe_retry on the single permitted retry.
const _scriptSafeRetry = Boolean(row.script_safe_retry);
const _safeRetryInstruction = (_scriptSafeRetry && s.safe_retry_instruction) ? String(s.safe_retry_instruction) : '';
const _prevError = String(row.previous_error || '').slice(0, 1500);
const _prevFailureType = String(row.previous_failure_type || '');

const userText = tpl(s.user_template, {
  project_id: row.project_id,
  product_name: row.product_name,
  target_market: row.target_market,
  target_language: row.target_language,
  creative_task_type: row.creative_task_type,
  product_understanding_json: row.product_understanding_json || '',
  audience_persona_json: row.audience_persona_json || '',
  tiktok_content_strategy_json: row.tiktok_content_strategy_json || '',
  selected_concept_name: row.selected_concept_name,
  selected_concept_json: row.selected_concept_json || '',
});

const overrideConstraints = [];
if (row.visual_expression || row.content_style) overrideConstraints.push('- content_style（内容风格，硬约束）：' + (row.visual_expression || row.content_style));
if (row.model_profile) overrideConstraints.push('- model_profile（人物/模特设定，硬约束）：' + row.model_profile);
if (row.usage_scene) overrideConstraints.push('- usage_scene（使用场景，硬约束）：' + row.usage_scene);
if (row.target_user) overrideConstraints.push('- target_user（目标用户，硬约束）：' + row.target_user);
const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (row.target_market || ''),
  '- target_language（视频字幕/口播/台词的目标语言，不是 JSON 字段的输出语言）：' + (row.target_language || ''),
  '- 【输出语言强制要求】所有 JSON 审核字段（concept_name、core_selling_angle、target_user、pain_point、usage_scene、visual_expression 等）必须使用中文，禁止用 target_language 作为 JSON 字段的输出语言。',
  '- creative_task_type 必须严格使用：' + (row.creative_task_type || ''),
  '- creative_task_type_rules：' + (row.creative_task_type_rules_json || '{}'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
  '- product_image_count：' + imageCount,
  ...overrideConstraints,
  ...(_scriptSafeRetry ? [
    '',
    '【安全自动重试上下文（系统注入，最多 1 次）】',
    '- previous_failure_type：' + (_prevFailureType || 'policy_or_parse'),
    '- previous_error（上次失败原因摘要，仅供规避，不得复述给用户）：' + (_prevError || '(未提供)'),
    '- 本次为安全重试：请严格输出合法 JSON 且仅 6 个 shot，避免触发内容政策；不得更改已选创意方向、target_market、target_language、creative_task_type。',
  ] : []),
].join('\n');

const _vlSource = (typeof row !== 'undefined' && row) ? row : (item.json || {});
const _vlMarket = String(_vlSource.target_market || '').trim();
const _vlLanguage = String(_vlSource.target_language || '').trim();
const _vlRules = prompts.voice_localization || {};
const _vlMarketKey = _vlMarket.toUpperCase();
const _vlRule = _vlRules[_vlMarketKey] || _vlRules[_vlMarket] || _vlRules.default || {};
const _vlAvoid = Array.from(new Set([
  ...(_vlRule.avoid || []),
  'robotic AI narration',
  'ad-like promotional tone',
  'machine-translation tone',
  'formal broadcaster speech',
].map((v) => String(v || '').trim()).filter(Boolean)));
const _vlOpenings = Array.isArray(_vlRule.opening_patterns) && _vlRule.opening_patterns.length
  ? _vlRule.opening_patterns.join(' / ')
  : '';
const voiceLocalizationBlock = [
  '',
  '【Target Market Voice Localization】',
  '- This rule layer only guides the AI first draft. If the user manually edits optional_voiceover_local later, the user edit has highest priority.',
  '- target_market: ' + (_vlMarket || 'not specified'),
  '- target_language: ' + (_vlLanguage || 'not specified'),
  '- optional_voiceover_local must follow target_market and target_language exactly.',
  '- Write optional_voiceover_local as natural local creator speech: conversational rhythm, short spoken phrases, clear emotion, believable pauses, and words that can be spoken within 8 seconds.',
  '- Tone: ' + (_vlRule.tone || 'natural, conversational, authentic local creator sharing'),
  _vlOpenings ? '- Local opening patterns to reference: ' + _vlOpenings : '',
  '- Avoid: ' + _vlAvoid.join('; '),
  '- Avoid robotic AI narration / ad-like voice / machine-translation tone. Do not write subtitles, captions, watermarks, or on-screen text instructions inside optional_voiceover_local.',
].filter(Boolean).join('\n');

const parts = [{ text: userText + hardConstraintBlock + voiceLocalizationBlock }];
if (imageCount >= 1 && image1Base64) parts.push({ inline_data: { mime_type: mime1, data: image1Base64 } });
if (imageCount >= 2 && image2Base64) parts.push({ inline_data: { mime_type: mime2, data: image2Base64 } });

return [
  {
    json: {
      ...row,
      image_1_path: image1Path,
      image_2_path: image2Path,
      image_1_base64: image1Base64,
      image_2_base64: image2Base64,
      image_1_mime: mime1,
      image_2_mime: mime2,
      image_count: imageCount,
      product_image_count: imageCount,
      request_body: {
        system_instruction: { parts: [{ text: s.system_instruction + (_safeRetryInstruction ? ('\n\n' + _safeRetryInstruction) : '') }] },
        contents: [{ role: 'user', parts }],
        generationConfig: s.generation_config,
      },
    },
  },
];

// Response adapter + extractor for Kie/OpenAI and Gemini native responses
const input = $json || {};

function parseMaybe(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (_) { return value; }
  }
  return value;
}

// n8n HTTP Request may wrap response in { data: "...json string..." }
let payload = parseMaybe(input.data != null ? input.data : input);
if (payload && typeof payload === 'object' && payload.data != null && !payload.choices && !payload.candidates) {
  payload = parseMaybe(payload.data);
}

// Error detection for Kie API errors
if (payload && typeof payload === 'object' && !payload.candidates && !payload.choices) {
  const errCode = payload.code;
  const errMsg  = payload.msg || payload.message;
  if (errCode !== undefined && errMsg) {
    const hint =
      String(errCode) === '422' ? '请求格式错误' :
      String(errCode) === '401' ? 'API Key 无效' :
      String(errCode) === '403' ? '账户权限不足或余额不足' :
      String(errCode) === '429' ? '请求频率超限' : '';
    throw new Error('Kie API 错误 ' + errCode + ': ' + errMsg + (hint ? '（' + hint + '）' : ''));
  }
}

const raw = (payload.candidates && payload.candidates[0] && payload.candidates[0].content && payload.candidates[0].content.parts && payload.candidates[0].content.parts[0])
  ? payload.candidates[0].content.parts[0].text || ''
  : (payload.choices && payload.choices[0] && payload.choices[0].message)
    ? payload.choices[0].message.content || ''
    : '';

if (!raw) {
  throw new Error('脚本框架生成返回空内容：' + JSON.stringify(payload).slice(0, 300));
}

function extractFirstJsonValue(text) {
  const raw = String(text || '').trim();
  if (!raw) throw new Error('脚本框架响应文本为空，无法提取 JSON');

  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = raw.match(fencedJson) || raw.match(fencedAny);
  const source = fenced?.[1] ? fenced[1].trim() : raw;

  for (const start of [source.indexOf('{'), source.indexOf('[')].filter((x) => x >= 0).sort((a, b) => a - b)) {
    const open = source[start];
    const close = open === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = start; i < source.length; i++) {
      const ch = source[i];
      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
      } else if (ch === open) {
        depth++;
      } else if (ch === close) {
        depth--;
        if (depth === 0) return source.slice(start, i + 1).trim();
      }
    }
  }

  return source;
}

let parsed = {};
try {
  parsed = JSON.parse(extractFirstJsonValue(raw));
} catch (error) {
  throw new Error('脚本框架生成返回无法提取合法 JSON: ' + error.message + '，原始返回前800字=' + String(raw).slice(0, 800));
}

// 尽量从上游节点取基础信息
const source =
  $('Code in JavaScript').first()?.json ||
  $('Edit Fields3').first()?.json ||
  $('脚本请求体组装').first()?.json ||
  {};


// Validate shots count: must be exactly 6
if (!Array.isArray(parsed.shots) || parsed.shots.length === 0) {
  throw new Error('脚本框架生成结果中 shots 为空数组。完整解析结果（前500字）：' + JSON.stringify(parsed).slice(0, 500));
}
if (parsed.shots.length !== 6) {
  throw new Error('脚本框架生成结果中 shots 数量不是 6 而是 ' + parsed.shots.length + '，不符合 6 镜头分镜要求。完整结果（前500字）：' + JSON.stringify(parsed).slice(0, 500));
}

return [
  {
    json: {
      project_id: source.project_id || '',
      product_name: source.product_name || '',
      target_market: source.target_market || '',
      target_language: source.target_language || '',
      creative_task_type: source.creative_task_type || '',

      selected_concept_name_original: parsed.script_overview?.selected_concept_name_original || '',
      script_concept_label: parsed.script_overview?.script_concept_label || '',
      script_goal: parsed.script_overview?.script_goal || '',
      visual_style: parsed.script_overview?.visual_style || '',
      identified_product_type: parsed.script_overview?.identified_product_type || '',
      product_presentation_logic: parsed.script_overview?.product_presentation_logic || '',
      core_visual_focus: parsed.script_overview?.core_visual_focus || '',
      total_shots: parsed.script_overview?.total_shots || 0,
      hook_strategy: parsed.script_overview?.hook_strategy || '',

      full_script_json: JSON.stringify(parsed),
      created_at: new Date().toISOString(),

      shots: parsed.shots || []
    }
  }
];

const fs = require('fs');
const path = require('path');
const os = require('os');
const process = require('process');

const row = $input.first().json || {};
const projectId = String(row.project_id || '').trim();
if (!projectId) throw new Error('写脚本框架上下文：缺少 project_id');
// Guard: refuse to write if shots are invalid
const inputShots = row.shots || [];
if (!Array.isArray(inputShots) || inputShots.length !== 6) {
  throw new Error('写脚本框架上下文：shots 数量不合法（期望 6，实际 ' + inputShots.length + '），拒绝写入脚本上下文和更新 project-state。');
}



