const process = require('process');
const fs = require('fs'), path = require('path'), os = require('os');

const KIE_BASE = 'https://api.kie.ai/api';
const KIE_TEXT_MODEL_DEFAULT = 'gemini-3.1-pro';

const CONFIG_CANDIDATES = [
  process.env.AI_VIDEO_CONFIG_PATH,
  (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'config', 'local-config.json') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'config', 'local-config.json')),
  process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, '版本测试', 'config', 'local-config.json') : null,
].filter(Boolean);

function loadConfigs() {
  const results = [];
  for (const p of CONFIG_CANDIDATES) {
    try { results.push({ path: p, cfg: JSON.parse(fs.readFileSync(p, 'utf8')) }); } catch(_) {}
  }
  return results;
}

function readKieConfig(taskStage) {
  for (const { cfg } of loadConfigs()) {
    const key = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.api_key) ||
      (cfg.kie && cfg.kie.api_key) ||
      ''
    ).trim();
    if (!key) continue;
    const taskModel = String((cfg.tasks && cfg.tasks[taskStage] && cfg.tasks[taskStage].model) || '').trim();
    const providerModel = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.text_model) ||
      (cfg.kie && cfg.kie.text_model) ||
      ''
    ).trim();
    const model = taskModel || providerModel || KIE_TEXT_MODEL_DEFAULT;
    const baseUrl = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.base_url) ||
      (cfg.kie && cfg.kie.base_url) ||
      KIE_BASE
    ).replace(/\/+$/, '');
    return { key, model, baseUrl };
  }
  const envKey = String(process.env.KIE_API_KEY || '').trim();
  if (envKey) return { key: envKey, model: KIE_TEXT_MODEL_DEFAULT, baseUrl: KIE_BASE };
  throw new Error('缺少 Kie API Key。请在「系统配置」填写 Kie API Key 并保存。');
}

function kieTextUrl(model, baseUrl) {
  const origin = baseUrl.endsWith('/api') ? baseUrl.slice(0, -4) : baseUrl.replace(/\/+$/, '');
  return origin + '/' + model + '/v1/chat/completions';
}

const { key, model, baseUrl } = readKieConfig('script_framework');
const url = kieTextUrl(model, baseUrl);
console.log('[WF02A-脚本框架] Kie text | model:', model);

const rawBody = $json.request_body || {};
const sysText = (rawBody.system_instruction && rawBody.system_instruction.parts && rawBody.system_instruction.parts[0] && rawBody.system_instruction.parts[0].text) || '';
const userParts = (rawBody.contents && rawBody.contents[0] && rawBody.contents[0].parts) || [];
const messages = [];
if (sysText) messages.push({ role: 'system', content: sysText });
const userContent = [];
for (const part of userParts) {
  if (part.text) userContent.push({ type: 'text', text: part.text });
}
const userMsg = userContent.length === 1 && userContent[0].type === 'text'
  ? { role: 'user', content: userContent[0].text }
  : { role: 'user', content: userContent };
messages.push(userMsg);
const kieBody = { model: model, messages, tool_choice: 'none' };

return [{ json: { ...$json, _stage: 'script_framework', _adapter: 'kie_openai_chat', _api_key: key, _model: model, _api_url: url, _auth_header: `Bearer ${key}`, request_body: kieBody } }];
